 */
public object FfiConverterTypeKeyWrapper: FfiConverter<KeyWrapper, Long> {
    internal val handleMap = UniffiHandleMap<KeyWrapper>()

    override fun lower(value: KeyWrapper): Long {
        if (value is KeyWrapperImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): KeyWrapper {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return KeyWrapperImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): KeyWrapper {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KeyWrapper) = 8UL

    override fun write(value: KeyWrapper, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



