sealed class SigningException: kotlin.Exception() {
    
    /**
     * `secret_key`/`public_key` hat nicht die für Ed25519 erforderliche Länge (32 Byte) —
     * oder ein `public_key` ist zwar 32 Byte lang, aber kein gültiger Ed25519-Kurvenpunkt.
     */
    class InvalidKeyLength(
        ) : SigningException() {
        override val message
            get() = ""
    }
    
    /**
     * `signature` hat nicht die für Ed25519 erforderliche Länge (64 Byte).
     */
    class InvalidSignatureLength(
        ) : SigningException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SigningException> {
        override fun lift(error_buf: RustBuffer.ByValue): SigningException = FfiConverterTypeSigningError.lift(error_buf)
    }

    
}

