sealed class WrapException: kotlin.Exception() {
    
    /**
     * Kotlin-seitige Wrap/Unwrap-Operation ist fehlgeschlagen — z. B. Keystore-Schlüssel nicht
     * verfügbar/invalidiert (Lockscreen-/Biometrie-Änderung invalidiert Keystore-Keys je nach
     * Spec), oder beim Unwrap die GCM-Auth-Tag-Prüfung nicht bestanden. Fail-Safe
     * (Invariante 6): Aufrufer behandeln jeden Fehlerfall einheitlich als "nicht entsperrbar",
     * nie als Sonderfall, der in offenen Zustand führen könnte.
     */
    class Failed(
        ) : WrapException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WrapException> {
        override fun lift(error_buf: RustBuffer.ByValue): WrapException = FfiConverterTypeWrapError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeWrapError : FfiConverterRustBuffer<WrapException> {
    override fun read(buf: ByteBuffer): WrapException {
        

        return when(buf.getInt()) {
            1 -> WrapException.Failed()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WrapException): ULong {
        return when(value) {
            is WrapException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: WrapException, buf: ByteBuffer) {
        when(value) {
            is WrapException.Failed -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}
        /**
         * Entschlüsselt ein [Envelope]. Bei falschem Schlüssel, falscher/fehlender AAD oder
         * manipuliertem Ciphertext schlägt dies fehl — Aufrufer müssen das als Fail-Safe-Signal
         * behandeln (Invariante 6: gesperrt bleiben, nicht "leer" interpretieren).
         */
    @Throws(OpenException::class) fun `open`(`key`: kotlin.ByteArray, `context`: kotlin.ByteArray, `envelope`: Envelope): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    uniffiRustCallWithError(OpenException) { _status ->
    UniffiLib.uniffi_connexias_engine_fn_func_open(
    
        
        FfiConverterByteArray.lower(`key`),
        FfiConverterByteArray.lower(`context`),
        FfiConverterTypeEnvelope.lower(`envelope`),_status)
}
    )
    }
    

        /**
         * Verschlüsselt `plaintext` mit AES-256-GCM. `context` ist die AAD (Zweck-/Empfänger-Bindung,
         * Konzept Abschnitt 2/10) — wird authentifiziert, aber nicht verschlüsselt/gespeichert im
         * Ciphertext; muss bei `open()` identisch erneut übergeben werden.
         */
    @Throws(SealException::class) fun `seal`(`key`: kotlin.ByteArray, `context`: kotlin.ByteArray, `plaintext`: kotlin.ByteArray): Envelope {
            return FfiConverterTypeEnvelope.lift(
    uniffiRustCallWithError(SealException) { _status ->
    UniffiLib.uniffi_connexias_engine_fn_func_seal(
    
        
        FfiConverterByteArray.lower(`key`),
        FfiConverterByteArray.lower(`context`),
        FfiConverterByteArray.lower(`plaintext`),_status)
}
    )
    }
    

        /**
         * Erzeugt `length` kryptografisch zufällige Bytes (`OsRng`, dieselbe CSPRNG-Quelle wie
         * Argon2-Salts in [crate::password] und AEAD-Nonces in [crate::aead] — ein Zufallsquellen-Pfad
         * für die ganze Engine).
         *
         * Der Zwischenpuffer ist [Zeroizing] — Meilenstein B.3 ist der erste Punkt, an dem die Engine
         * ein echtes Geheimnis in der Hand hält (B.1-Notiz in [crate::aead]/[crate::password]: "echte
         * Geheimnisse kommen erst mit B.3"). Das schützt nur Rusts eigene Kopie bei frühem
         * Return/Panic vor dem Verlassen dieser Funktion — der Rückgabewert selbst muss als
         * `Vec<u8>` die FFI-Grenze überqueren (UniFFI kennt keinen zeroisierenden Rückgabetyp) und ist
         * ab dort nicht mehr kontrollierbar; siehe Kotlin-seitige Pufferbehandlung in `KeystoreKek`.
         */ fun `generateDek`(`length`: kotlin.UInt): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_connexias_engine_fn_func_generate_dek(
    
        
        FfiConverterUInt.lower(`length`),_status)
}
    )
    }
    

        /**
         * Leitet `length` Bytes Schlüsselmaterial aus `input_key_material` ab. `salt` sollte zufällig
         * und pro Kontext eindeutig sein (kann leer sein, dann wird ein Null-Salt der Hash-Länge
         * verwendet — HKDF-Standardverhalten); `info` bindet den Zweck (z. B. `b"warden:registry:kek"`)
         * und verhindert, dass aus demselben Eingangsmaterial versehentlich derselbe Schlüssel für
         * zwei verschiedene Zwecke entsteht.
         *
         * `length` ist `u32` statt `usize` — UniFFI-Exports (Meilenstein B.2) brauchen plattform-
         * unabhängige Breiten, `usize` ist dafür nicht geeignet.
         */
    @Throws(KdfException::class) fun `deriveKey`(`inputKeyMaterial`: kotlin.ByteArray, `salt`: kotlin.ByteArray, `info`: kotlin.ByteArray, `length`: kotlin.UInt): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    uniffiRustCallWithError(KdfException) { _status ->
    UniffiLib.uniffi_connexias_engine_fn_func_derive_key(
    
        
        FfiConverterByteArray.lower(`inputKeyMaterial`),
        FfiConverterByteArray.lower(`salt`),
        FfiConverterByteArray.lower(`info`),
        FfiConverterUInt.lower(`length`),_status)
}
    )
    }
    

